mapper.insert:
INSERT INTO settings (s_key, s_value)
VALUES (#{s_key}, #{s_value})
ON DUPLICATE KEY UPDATE s_value = #{s_value}

mapper.select:
SELECT a_idx, a_id, a_name, a_email, a_addr, a_phone, a_pwd
  FROM admin
 WHERE a_idx = #{a_idx}

mapper.update:
UPDATE admin
   SET a_name  = #{a_name},
       a_email = #{a_email},
       a_phone = #{a_phone}
 WHERE a_idx = #{a_idx}

UPDATE admin
   SET a_pwd = #{a_pwd}
 WHERE a_idx = #{a_idx}

UPDATE inquiry_template
   SET t_title   = #{t_title},
       t_content = #{t_content}
 WHERE t_idx = #{t_idx}
